/**
 * @distilled.cloud/proxmox — Proxmox VE API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from PVE's own
 * `apidata.js`, mirrored under `specs/`). Everything else in this folder is
 * hand-written.
 *
 * One module per PVE top-level path segment — `access`, `cluster`,
 * `nodes`, `pools`, `storage`, `version` — the same split the vendor's own
 * api-viewer uses.
 *
 * @example
 * ```ts
 * import * as Proxmox from "@distilled.cloud/proxmox";
 *
 * const status = yield* Proxmox.Services.nodes.getNodeTaskStatus({
 *   node: "pve1",
 *   upid: "UPID:pve1:00001234:...",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ProxmoxProtocol,
  type ProxmoxOpError,
  type ProxmoxOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
export { awaitTask, type TaskRef, type AwaitTaskOptions } from "./task.ts";
